\encoding UTF8
\copy (WITH vp AS (SELECT *, (pipeline_metadata::jsonb ? 'ai_extras' AND (pipeline_metadata::jsonb->'ai_extras') ? 'topic_match_quality' AND ((pipeline_metadata::jsonb->'ai_extras')->>'topic_match_quality')='fallback') AS b_fb, (pipeline_metadata::jsonb ? 'demoted_at') AS b_dem, (quality_review_status NOT IN ('human_verified','auto_judged_high')) AS b_st, (id IN (SELECT id FROM gate2c_demoted)) AS b_g2c FROM question_bank WHERE pipeline_metadata::jsonb ? 'verified_provisional') SELECT json_build_object('id',id,'subj',subject_area,'exam',exam_type,'q',question_text,'a',option_a,'b',option_b,'c',option_c,'d',option_d,'e',option_e,'key',correct_answer) FROM vp WHERE b_st AND NOT b_fb AND NOT b_dem AND NOT b_g2c ORDER BY md5(id::text)) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_wave1/vp116.csv' CSV
